INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Formfaktor dasselbe wie die Leistung einer Hardware?', 2, '[{"text": "Nein", "correct": true, "because": "Größe vs. Leistung"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Konzepte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt der Formfaktor?', 3, '[{"text": "Kompatibilität von Hardware sicherstellen", "correct": true, "because": "Standardisierung"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Kein Sicherheitsfokus"}, {"text": "Netzwerkgeschwindigkeit erhöhen", "correct": false, "because": "Kein Netzwerkbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele gibt es für Formfaktoren?', 5, '[{"text": "ATX", "correct": true, "because": "Mainboard-Standard"}, {"text": "2,5 Zoll", "correct": true, "because": "Festplattengröße"}, {"text": "Papierformat", "correct": false, "because": "Kein Hardwarebezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Formfaktor definiert die physische Größe. b) Er bestimmt die Softwareleistung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kein Softwarebezug"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Formfaktor?', 4, '[{"text": "Abmessungen", "correct": false, "because": "Kernmerkmal"}, {"text": "Kompatibilität", "correct": false, "because": "Grundlage"}, {"text": "Papiergewicht", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Formfaktor die Leistung beeinflusst?', 2, '[{"text": "Nein", "correct": true, "because": "Größe, nicht Leistung"}, {"text": "Ja", "correct": false, "because": "Indirekt möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Formfaktor ist typisch für Mainboards?', 3, '[{"text": "ATX", "correct": true, "because": "Standardgröße"}, {"text": "SATA", "correct": false, "because": "Schnittstelle"}, {"text": "USB", "correct": false, "because": "Anschluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein standardisierter Formfaktor?', 5, '[{"text": "Kompatibilität", "correct": true, "because": "Passt zusammen"}, {"text": "Einfacher Austausch", "correct": true, "because": "Einheitliche Größe"}, {"text": "Schnellere Datenübertragung", "correct": false, "because": "Kein Leistungsbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Der Formfaktor beeinflusst die Gehäusegröße. b) Er definiert die CPU-Geschwindigkeit. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kein Leistungsbezug"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Formfaktor?', 4, '[{"text": "Abmessungen", "correct": false, "because": "Größendefinition"}, {"text": "Kompatibilitätsstandards", "correct": false, "because": "Einheitlichkeit"}, {"text": "Farbcodierung", "correct": true, "because": "Kein technischer Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Formfaktor nur für Festplatten relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Mainboards, Netzteile"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Formfaktoren gibt es für Festplatten?', 4, '[{"text": "3,5 Zoll", "correct": true, "because": "Desktop"}, {"text": "2,5 Zoll", "correct": true, "because": "Laptop"}, {"text": "A4", "correct": false, "because": "Papierformat"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der Formfaktor die Leistung bestimmt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Größe, nicht Leistung"}, {"text": "Ja", "correct": false, "because": "Indirekt möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Formfaktor?', 3, '[{"text": "Kompatibilität", "correct": true, "because": "Passt ins System"}, {"text": "Schriftart", "correct": false, "because": "Irrelevant"}, {"text": "Gewicht", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Formfaktor ist standardisiert. b) Er beeinflusst die Software.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kein Softwarebezug"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hardware wird durch Formfaktoren definiert?', 5, '[{"text": "Mainboards", "correct": true, "because": "ATX, Micro-ATX"}, {"text": "Festplatten", "correct": true, "because": "2,5/3,5 Zoll"}, {"text": "Papierdrucker", "correct": false, "because": "Kein Formfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Formfaktor unwichtig?', 3, '[{"text": "Größe", "correct": false, "because": "Kernmerkmal"}, {"text": "Kompatibilität", "correct": false, "because": "Grundlage"}, {"text": "Papierdokumentation", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Formfaktor die Kühlung beeinflussen?', 3, '[{"text": "Ja", "correct": true, "because": "Platz für Lüfter"}, {"text": "Nein", "correct": false, "because": "Indirekt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Formfaktor nur für PCs gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Server, Laptops"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für einen Formfaktor zentral?', 4, '[{"text": "Physische Abmessungen", "correct": true, "because": "Kernprinzip"}, {"text": "Softwareleistung", "correct": false, "because": "Kein Bezug"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]');
